
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mtask_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mtask", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.361651813648453e+00, -5.252631800472818e+00, -5.099763019508422e+00, -4.887767962914723e+00, -4.598363445915433e+00, -4.211914025292845e+00, -3.711297157150101e+00, -3.088052268260474e+00, -2.349162260182362e+00, -1.524574967551666e+00, -6.669474300745564e-01, -4.802500246182212e-01, -6.367235670986768e-01, -5.448046129889824e-01, -3.668960374522638e-01, -1.909519373438233e-01, -6.921367351009104e-02, -2.374808736929905e-02, -4.072340251477162e-03, -1.953791448793726e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


